async def act(page):
    """
    - Navigate (relative) to the Sample Page at /?page_id=2 to look for the site's visible search widget.
    - Locate complementary region (role="complementary") if present, then locate a search input (role="searchbox" preferred, fallback to role="textbox").
    - Fill the search input with 'DeepSeek' and activate the search by clicking a Search button inside the complementary region (preferred), falling back to the first button there, then a global Search button, and finally pressing Enter in the input.
    - Wait for results to appear in role="main" and collect role="article" children. Click the bottom-most result: prefer clicking the first link inside the last article via the full parent path; if no link exists, click the article container itself. That click is the final action because it is expected to navigate away.
    """

    # 1) Go to the Sample Page where a search widget is more likely to be present.
    await page.goto("/?page_id=2")
    await page.wait_for_load_state("networkidle")

    # 2) Try to find the complementary region and a search input inside it.
    comp = None
    try:
        comp_locator = page.get_by_role("complementary")
        if await comp_locator.count() > 0:
            comp = comp_locator.nth(0)
            # try to ensure it's visible but don't fail if it's not
            try:
                await comp.wait_for(state="visible", timeout=2000)
            except Exception:
                pass
    except Exception:
        comp = None

    search_input = None
    # Prefer a searchbox inside complementary region
    if comp is not None:
        try:
            sb = comp.get_by_role("searchbox")
            if await sb.count() > 0:
                search_input = sb.nth(0)
        except Exception:
            search_input = None

        if search_input is None:
            try:
                tb = comp.get_by_role("textbox")
                if await tb.count() > 0:
                    search_input = tb.nth(0)
            except Exception:
                search_input = None

    # Fallback to global searchbox/textbox if not found in complementary
    if search_input is None:
        try:
            global_sb = page.get_by_role("searchbox")
            if await global_sb.count() > 0:
                search_input = global_sb.nth(0)
        except Exception:
            search_input = None

    if search_input is None:
        try:
            global_tb = page.get_by_role("textbox")
            if await global_tb.count() > 0:
                search_input = global_tb.nth(0)
        except Exception:
            search_input = None

    # If we couldn't find any search input, abort (nothing we can do to use the site search bar)
    if search_input is None:
        return

    # 3) Fill the search input with the keyword
    await search_input.fill("DeepSeek")

    # 4) Trigger the search. Try several fallbacks in order.
    triggered = False

    # Preferred: button named 'Search' inside complementary region
    if comp is not None:
        try:
            search_btns = comp.get_by_role("button", name="Search")
            if await search_btns.count() > 0:
                # use full parent path when interacting with a control that belongs to an element
                await comp.get_by_role("button", name="Search").nth(0).click()
                triggered = True
        except Exception:
            triggered = False

    # Fallback: first button inside complementary region
    if not triggered and comp is not None:
        try:
            any_btns = comp.get_by_role("button")
            if await any_btns.count() > 0:
                await comp.get_by_role("button").nth(0).click()
                triggered = True
        except Exception:
            triggered = False

    # Fallback: global button named 'Search'
    if not triggered:
        try:
            global_search_btns = page.get_by_role("button", name="Search")
            if await global_search_btns.count() > 0:
                await page.get_by_role("button", name="Search").nth(0).click()
                triggered = True
        except Exception:
            triggered = False

    # Last resort: press Enter in the search input
    if not triggered:
        try:
            await search_input.press("Enter")
            triggered = True
        except Exception:
            triggered = False

    if not triggered:
        # Could not activate search
        return

    # 5) Wait for results: role='main' should contain role='article' children.
    main = None
    try:
        main_locator = page.get_by_role("main")
        if await main_locator.count() > 0:
            main = main_locator.nth(0)
            try:
                await main.wait_for(state="visible", timeout=5000)
            except Exception:
                # fallback to networkidle
                await page.wait_for_load_state("networkidle")
        else:
            await page.wait_for_load_state("networkidle")
            main_locator = page.get_by_role("main")
            if await main_locator.count() > 0:
                main = main_locator.nth(0)
    except Exception:
        # final fallback: wait and then attempt to get main
        try:
            await page.wait_for_load_state("networkidle")
            main_locator = page.get_by_role("main")
            if await main_locator.count() > 0:
                main = main_locator.nth(0)
        except Exception:
            main = None

    if main is None:
        return

    # 6) Find all article results and click the bottom-most (last) one. Use full parent paths for clicks.
    articles = main.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count == 0:
        return

    last_index = article_count - 1

    # Prefer clicking the first link inside the last article
    try:
        link_locator = main.get_by_role("article").nth(last_index).get_by_role("link")
        if await link_locator.count() > 0:
            # Final action: click the first link inside the bottom-most article
            await main.get_by_role("article").nth(last_index).get_by_role("link").nth(0).click()
            return
    except Exception:
        pass

    # Fallback final action: click the article container itself
    await main.get_by_role("article").nth(last_index).click()

